// === HELPER COMPONENTS ====================================================

// Paper texture / grain background
function PaperBg({ children, style = {}, className = "" }) {
  return (
    <div
      className={className}
      style={{
        position: "relative",
        background: C.paper,
        backgroundImage:
          "radial-gradient(rgba(180,140,80,0.10) 1px, transparent 1px), radial-gradient(rgba(120,80,40,0.06) 1px, transparent 1px)",
        backgroundSize: "3px 3px, 7px 7px",
        backgroundPosition: "0 0, 1.5px 1.5px",
        ...style,
      }}
    >
      {children}
    </div>
  );
}

// Tape strip
function Tape({ rotation = -8, top = -14, left = "50%", width = 90, color = "rgba(255, 230, 150, 0.62)" }) {
  return (
    <div
      style={{
        position: "absolute",
        top,
        left,
        transform: `translateX(-50%) rotate(${rotation}deg)`,
        width,
        height: 26,
        background: color,
        boxShadow: "0 2px 4px rgba(0,0,0,0.12)",
        borderLeft: "1px dashed rgba(0,0,0,0.08)",
        borderRight: "1px dashed rgba(0,0,0,0.08)",
        zIndex: 5,
        pointerEvents: "none",
      }}
    />
  );
}

