// Floating decoration that wobbles
function FloatingDoodle({ children, top, left, right, delay = 0, duration = 4, rotation = 0 }) {
  return (
    <div
      style={{
        position: "absolute",
        top,
        left,
        right,
        animation: `floatWobble ${duration}s ease-in-out infinite`,
        animationDelay: `${delay}s`,
        transform: `rotate(${rotation}deg)`,
        zIndex: 1,
        pointerEvents: "none",
      }}
    >
      {children}
    </div>
  );
}

