function RsvpScreen({ onSubmit, status }) {
  const [name, setName] = useState("");
  const [hovering, setHovering] = useState(null);

  const handleClick = (choice) => {
    // If a Tally form URL is configured, open it in a new tab with prefilled params
    if (TALLY_URL) {
      const params = new URLSearchParams({
        name: name || "",
        status: choice === "yes" ? "буду" : "не зможу",
      }).toString();
      const sep = TALLY_URL.includes("?") ? "&" : "?";
      try {
        window.open(TALLY_URL + sep + params, "_blank", "noopener,noreferrer");
      } catch (e) {
        // ignore — still show the local confirmation below
      }
    }
    onSubmit(choice, name || "ти");
  };

  return (
    <PaperBg style={{ padding: "44px 24px 60px", position: "relative", overflow: "hidden" }}>
      <FloatingDoodle top={22} left={14} delay={0.1} rotation={-6}>
        <Star size={32} color={C.coralDeep} stroke={3} />
      </FloatingDoodle>
      <FloatingDoodle top={28} right={18} delay={0.5} rotation={10}>
        <Sparkle size={24} color={C.tealDeep} />
      </FloatingDoodle>

      <div style={{ position: "relative", zIndex: 2 }}>
        <div
          style={{
            fontFamily: "'Permanent Marker', cursive",
            fontSize: 13,
            color: C.coralDeep,
            letterSpacing: "0.1em",
            transform: "rotate(-2deg)",
            display: "inline-block",
          }}
        >
          PART 5 / RSVP
        </div>
        <h2
          style={{
            fontFamily: "'Fraunces', serif",
            fontStyle: "italic",
            fontWeight: 900,
            fontSize: 46,
            color: C.ink,
            margin: "4px 0 4px",
            lineHeight: 0.95,
            letterSpacing: "-0.02em",
          }}
        >
          ну то як?
        </h2>
        <Squiggle width={130} color={C.coralDeep} stroke={3} />

        {status === null && (
          <>
            <div
              style={{
                fontFamily: "'Fraunces', serif",
                fontWeight: 700,
                fontSize: 18,
                color: C.ink,
                marginTop: 22,
                marginBottom: 8,
              }}
            >
              як тебе звати?
            </div>
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="імʼя сюди..."
              style={{
                width: "100%",
                padding: "12px 14px",
                fontFamily: "'Caveat', cursive",
                fontSize: 22,
                color: C.ink,
                background: C.paper,
                border: `2.5px solid ${C.ink}`,
                borderRadius: 12,
                outline: "none",
                boxShadow: `3px 3px 0 ${C.coralDeep}`,
                boxSizing: "border-box",
              }}
            />

            <div
              style={{
                marginTop: 26,
                display: "grid",
                gridTemplateColumns: "1fr 1fr",
                gap: 14,
              }}
            >
              <button
                onClick={() => handleClick("yes")}
                onMouseEnter={() => setHovering("yes")}
                onMouseLeave={() => setHovering(null)}
                style={{
                  fontFamily: "'Fraunces', serif",
                  fontStyle: "italic",
                  fontWeight: 900,
                  fontSize: 22,
                  background: hovering === "yes" ? C.coralDeep : C.coral,
                  color: C.cream,
                  border: `3px solid ${C.ink}`,
                  borderRadius: 14,
                  padding: "20px 12px",
                  cursor: "pointer",
                  boxShadow: hovering === "yes" ? `2px 2px 0 ${C.ink}` : `5px 5px 0 ${C.ink}`,
                  transform: hovering === "yes" ? "translate(3px, 3px)" : "none",
                  transition: "all 0.15s ease",
                  lineHeight: 1.05,
                }}
              >
                буду! ✿
                <div
                  style={{
                    fontFamily: "'Caveat', cursive",
                    fontStyle: "normal",
                    fontWeight: 600,
                    fontSize: 15,
                    marginTop: 2,
                    opacity: 0.9,
                  }}
                >
                  100%
                </div>
              </button>
              <button
                onClick={() => handleClick("no")}
                onMouseEnter={() => setHovering("no")}
                onMouseLeave={() => setHovering(null)}
                style={{
                  fontFamily: "'Fraunces', serif",
                  fontStyle: "italic",
                  fontWeight: 800,
                  fontSize: 19,
                  background: hovering === "no" ? C.tealDeep : C.teal,
                  color: C.cream,
                  border: `3px solid ${C.ink}`,
                  borderRadius: 14,
                  padding: "20px 12px",
                  cursor: "pointer",
                  boxShadow: hovering === "no" ? `2px 2px 0 ${C.ink}` : `5px 5px 0 ${C.ink}`,
                  transform: hovering === "no" ? "translate(3px, 3px)" : "none",
                  transition: "all 0.15s ease",
                  lineHeight: 1.05,
                }}
              >
                не зможу
                <div
                  style={{
                    fontFamily: "'Caveat', cursive",
                    fontStyle: "normal",
                    fontWeight: 600,
                    fontSize: 15,
                    marginTop: 2,
                    opacity: 0.9,
                  }}
                >
                  буде сумно :(
                </div>
              </button>
            </div>
            <div
              style={{
                fontFamily: "'JetBrains Mono', monospace",
                fontSize: 10.5,
                color: C.ink,
                opacity: 0.5,
                textAlign: "center",
                marginTop: 18,
                letterSpacing: "0.1em",
              }}
            >
              {TALLY_URL
                ? "відкриється коротка форма для підтвердження"
                : "відповідь долетить до нас одразу"}
            </div>
          </>
        )}

        {status === "yes" && (
          <div style={{ marginTop: 26, textAlign: "center" }}>
            <Confetti />
            <div
              style={{
                fontFamily: "'Fraunces', serif",
                fontStyle: "italic",
                fontWeight: 900,
                fontSize: 42,
                color: C.coralDeep,
                lineHeight: 0.95,
                animation: "bigPop 0.5s cubic-bezier(0.34, 1.56, 0.64, 1)",
              }}
            >
              сонце!! 🌞
            </div>
            <div
              style={{
                fontFamily: "'Caveat', cursive",
                fontSize: 22,
                color: C.ink,
                marginTop: 8,
                lineHeight: 1.3,
              }}
            >
              чекаємо на тебе 25 травня
              <br />
              на пляжі (ну майже)
            </div>
            <div
              style={{
                fontFamily: "'JetBrains Mono', monospace",
                fontSize: 12,
                color: C.tealDeep,
                marginTop: 16,
                letterSpacing: "0.1em",
              }}
            >
              [ збережено ✓ ]
            </div>
          </div>
        )}

        {status === "no" && (
          <div style={{ marginTop: 26, textAlign: "center" }}>
            <div
              style={{
                fontFamily: "'Fraunces', serif",
                fontStyle: "italic",
                fontWeight: 900,
                fontSize: 38,
                color: C.tealDeep,
                lineHeight: 0.95,
              }}
            >
              ехх, ну ладно
            </div>
            <div
              style={{
                fontFamily: "'Caveat', cursive",
                fontSize: 22,
                color: C.ink,
                marginTop: 8,
                lineHeight: 1.3,
              }}
            >
              випʼємо за тебе{" "}
              <span style={{ color: C.coralDeep }}>заочно</span>
              <br />
              <span style={{ fontSize: 18 }}>(і фоточки скинемо)</span>
            </div>
          </div>
        )}
      </div>
    </PaperBg>
  );
}

// Confetti for RSVP yes
function Confetti() {
  const pieces = Array.from({ length: 24 }).map((_, i) => {
    const colors = [C.coral, C.coralDeep, C.teal, C.tealDeep, C.sand, "#f5d76e"];
    const c = colors[i % colors.length];
    const left = Math.random() * 100;
    const delay = Math.random() * 0.5;
    const dur = 1.6 + Math.random() * 1.2;
    const size = 6 + Math.random() * 8;
    const rot = Math.random() * 360;
    return { c, left, delay, dur, size, rot, key: i };
  });
  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        pointerEvents: "none",
        overflow: "hidden",
      }}
    >
      {pieces.map((p) => (
        <span
          key={p.key}
          style={{
            position: "absolute",
            top: -20,
            left: `${p.left}%`,
            width: p.size,
            height: p.size * 1.6,
            background: p.c,
            transform: `rotate(${p.rot}deg)`,
            animation: `confettiFall ${p.dur}s linear ${p.delay}s forwards`,
            borderRadius: 2,
          }}
        />
      ))}
    </div>
  );
}

// === MAIN APP =============================================================

export default function Invitation() {
  const [stage, setStage] = useState("hero"); // hero | full
  const [rsvp, setRsvp] = useState(null);
  const detailsRef = useRef(null);

  useEffect(() => {
    ensureFonts();
  }, []);

  const handleContinue = () => {
    setStage("full");
    setTimeout(() => {
      if (detailsRef.current) {
        detailsRef.current.scrollIntoView({ behavior: "smooth", block: "start" });
      }
    }, 80);
  };

  const handleRsvp = (status, name) => {
    setRsvp(status);
  };

  return (
    <div
      style={{
        width: "100%",
        minHeight: "100vh",
        background: C.paper,
        fontFamily: "'Fraunces', serif",
        color: C.ink,
      }}
    >
      <style>{`
        @keyframes floatWobble {
          0%, 100% { transform: translateY(0) rotate(var(--r, 0deg)); }
          50% { transform: translateY(-8px) rotate(var(--r, 0deg)); }
        }
        @keyframes sunPulse {
          0%, 100% { transform: scale(1); opacity: 0.85; }
          50% { transform: scale(1.05); opacity: 1; }
        }
        @keyframes twentyBounce {
          0%, 100% { transform: translateY(4px) rotate(-3deg); }
          50% { transform: translateY(-3px) rotate(2deg); }
        }
        @keyframes photoSwayA {
          0%, 100% { transform: rotate(-6deg) translateY(0); }
          50% { transform: rotate(-5deg) translateY(-4px); }
        }
        @keyframes photoSwayB {
          0%, 100% { transform: rotate(7deg) translateY(0); }
          50% { transform: rotate(6deg) translateY(-4px); }
        }
        @keyframes confettiFall {
          0% { transform: translateY(-20px) rotate(0deg); opacity: 1; }
          100% { transform: translateY(360px) rotate(720deg); opacity: 0; }
        }
        @keyframes bigPop {
          0% { transform: scale(0.4); opacity: 0; }
          70% { transform: scale(1.1); }
          100% { transform: scale(1); opacity: 1; }
        }
        @keyframes slideUp {
          from { opacity: 0; transform: translateY(30px); }
          to { opacity: 1; transform: translateY(0); }
        }
        ::selection {
          background: ${C.coral};
          color: ${C.cream};
        }
        button:focus-visible {
          outline: 3px solid ${C.coralDeep};
          outline-offset: 2px;
        }
        input:focus {
          border-color: ${C.coralDeep} !important;
        }
      `}</style>

      <HeroScreen onContinue={handleContinue} />

      {stage === "full" && (
        <div style={{ animation: "slideUp 0.6s ease" }}>
          <div ref={detailsRef}>
            <DetailsScreen />
          </div>
          <DresscodeScreen />
          <BringScreen />
          <MusicScreen />
          <RsvpScreen onSubmit={handleRsvp} status={rsvp} />
        </div>
      )}
    </div>
  );
}
